import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CorrelationChartProps = Record<string, any>;

const CorrelationChart: React.FC<CorrelationChartProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = true,
  durationInSeconds = 6,
  dollarsSpent = 12500,
  totalViews = 850000,
  totalEngagement = 45000,
  viewsColor = "#00e5ff",
  engagementColor = "#a600ff",
  spendColor = "#00ff73",
  textColor = "#ffffff",
  chartBackgroundColor = "#1a1a1a",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Space Grotesk", "Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Ensure duration ranges are strictly monotonic
  const safeDuration = Math.max(3, durationInSeconds);
  const animStart = fps * 0.5; // Start at 0.5s
  const animEnd = Math.max(animStart + 1, fps * safeDuration - fps * 1); // End 1s before finish

  // Core Progress Easing
  const rawProgress = interpolate(frame, [animStart, animEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });

  // Number Formatters
  const formatNumber = (num: number) => new Intl.NumberFormat("en-US").format(num);
  const formatCurrency = (num: number) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      maximumFractionDigits: 0,
    }).format(num);

  // Interpolated Values
  const currentSpend = Math.floor(rawProgress * dollarsSpent);
  
  // We apply a slight exponential curve to views and engagement to show accelerating correlation
  const curveFactor = Math.pow(rawProgress, 1.5);
  const currentViews = Math.floor(curveFactor * totalViews);
  const currentEng = Math.floor(curveFactor * totalEngagement);

  // Entrance Animations
  const entrySpring = spring({ fps, frame, config: { damping: 14 } });
  const containerY = interpolate(entrySpring, [0, 1], [100, 0]);
  const containerOpacity = interpolate(entrySpring, [0, 1], [0, 1]);

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Chart dimensions and coordinates
  const chartViewBox = "0 0 1000 400";
  // Views line path (smooth cubic bezier going upward)
  const viewsPath = "M 0 380 C 300 370, 600 200, 1000 40";
  // Engagement line path (smooth cubic bezier going upward, slightly lower)
  const engPath = "M 0 390 C 400 385, 700 280, 1000 150";

  // Dynamic clipping for the graph drawing effect
  const clipWidth = rawProgress * 100;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: textColor,
        transition: "none",
      }}
    >
      <div
        style={{
          width: width * 0.85,
          height: height * 0.8,
          display: "flex",
          flexDirection: "column",
          gap: "40px",
          transform: `translateY(${containerY}px)`,
          opacity: containerOpacity,
          transition: "none",
        }}
      >
        {/* Top Metrics Row */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "center",
            width: "100%",
            transition: "none",
          }}
        >
          {/* Spend Metric */}
          <div style={{ flex: 1, transition: "none" }}>
            <p
              style={{
                margin: 0,
                fontSize: "24px",
                fontWeight: 600,
                color: spendColor,
                textTransform: "uppercase",
                letterSpacing: "2px",
                transition: "none",
              }}
            >
              Ad Spend
            </p>
            <h1
              style={{
                margin: "10px 0 0 0",
                fontSize: "72px",
                fontWeight: 700,
                fontFamily: "Space Grotesk",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {formatCurrency(currentSpend)}
            </h1>
          </div>

          {/* Views Metric */}
          <div style={{ flex: 1, transition: "none" }}>
            <p
              style={{
                margin: 0,
                fontSize: "24px",
                fontWeight: 600,
                color: viewsColor,
                textTransform: "uppercase",
                letterSpacing: "2px",
                transition: "none",
              }}
            >
              Total Views
            </p>
            <h1
              style={{
                margin: "10px 0 0 0",
                fontSize: "72px",
                fontWeight: 700,
                fontFamily: "Space Grotesk",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {formatNumber(currentViews)}
            </h1>
          </div>

          {/* Engagement Metric */}
          <div style={{ flex: 1, transition: "none" }}>
            <p
              style={{
                margin: 0,
                fontSize: "24px",
                fontWeight: 600,
                color: engagementColor,
                textTransform: "uppercase",
                letterSpacing: "2px",
                transition: "none",
              }}
            >
              Engagements
            </p>
            <h1
              style={{
                margin: "10px 0 0 0",
                fontSize: "72px",
                fontWeight: 700,
                fontFamily: "Space Grotesk",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {formatNumber(currentEng)}
            </h1>
          </div>
        </div>

        {/* Chart Area */}
        <div
          style={{
            flex: 1,
            position: "relative",
            backgroundColor: chartBackgroundColor,
            borderRadius: "24px",
            overflow: "hidden",
            boxShadow: "0 20px 40px rgba(0,0,0,0.3)",
            border: `1px solid ${textColor}22`,
            transition: "none",
          }}
        >
          {/* Background Grid */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              padding: "40px 0",
              opacity: 0.1,
              transition: "none",
            }}
          >
            {[...Array(5)].map((_, i) => (
              <div
                key={i}
                style={{
                  width: "100%",
                  height: "2px",
                  backgroundColor: textColor,
                  transition: "none",
                }}
              />
            ))}
          </div>

          {/* Animated SVG Lines & Gradients */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              // Clip path reveals the graph from left to right
              clipPath: `inset(0% ${100 - clipWidth}% 0% 0%)`,
              transition: "none",
            }}
          >
            <svg
              viewBox={chartViewBox}
              preserveAspectRatio="none"
              style={{
                width: "100%",
                height: "100%",
                transition: "none",
                display: "block",
              }}
            >
              <defs>
                <linearGradient id="viewsGrad" x1="0" x2="0" y1="0" y2="1">
                  <stop offset="0%" stopColor={viewsColor} stopOpacity="0.4" />
                  <stop offset="100%" stopColor={viewsColor} stopOpacity="0.0" />
                </linearGradient>
                <linearGradient id="engGrad" x1="0" x2="0" y1="0" y2="1">
                  <stop offset="0%" stopColor={engagementColor} stopOpacity="0.4" />
                  <stop offset="100%" stopColor={engagementColor} stopOpacity="0.0" />
                </linearGradient>
              </defs>

              {/* Views Area Fill */}
              <path
                d={`${viewsPath} L 1000 400 L 0 400 Z`}
                fill="url(#viewsGrad)"
                style={{ transition: "none" }}
              />
              
              {/* Engagement Area Fill */}
              <path
                d={`${engPath} L 1000 400 L 0 400 Z`}
                fill="url(#engGrad)"
                style={{ transition: "none" }}
              />

              {/* Views Line */}
              <path
                d={viewsPath}
                fill="none"
                stroke={viewsColor}
                strokeWidth="6"
                strokeLinecap="round"
                style={{ transition: "none" }}
              />

              {/* Engagement Line */}
              <path
                d={engPath}
                fill="none"
                stroke={engagementColor}
                strokeWidth="6"
                strokeLinecap="round"
                style={{ transition: "none" }}
              />
            </svg>
          </div>

          {/* Scrubber Line (Vertical indicator for Spend correlation) */}
          <div
            style={{
              position: "absolute",
              top: 0,
              bottom: 0,
              left: `${clipWidth}%`,
              width: "2px",
              backgroundColor: spendColor,
              boxShadow: `0 0 10px ${spendColor}`,
              opacity: rawProgress > 0 && rawProgress < 1 ? 1 : 0,
              transition: "none",
              zIndex: 10,
            }}
          >
            {/* Scrubber Dot */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: "translate(-50%, -50%)",
                width: "12px",
                height: "12px",
                backgroundColor: "#fff",
                border: `3px solid ${spendColor}`,
                borderRadius: "50%",
                transition: "none",
              }}
            />
          </div>
        </div>

        {/* X-Axis Labels */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            opacity: 0.5,
            fontSize: "18px",
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "1px",
            transition: "none",
          }}
        >
          <span>Initiation</span>
          <span>Growth Phase</span>
          <span>Scaling</span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CorrelationChart;